#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int tallestBillboard(vector<int>& rods) {
        unordered_map<int, int> dp = {{0, 0}};
        for (int r : rods) {
            auto cur = dp;
            for (auto [d, h] : cur) {
                dp[d + r] = max(dp[d + r], h);
                dp[abs(d - r)] = max(dp[abs(d - r)], h + min(d, r));
            }
        }
        return dp[0];
    }
};
